{
  "schema_version": "z-event-v1",
  "chapter": 3,
  "events": [
    {
      "event_id": "EV-C0003-01",
      "event": "周明瑞确定计划后审视克莱恩残留的记忆碎片。",
      "anchors": [{"anchor_id": "E0002"}, {"anchor_id": "E0005"}]
    },
    {
      "event_id": "EV-C0003-02",
      "event": "周明瑞关上管道阀门并熄灭壁灯后坐下摩挲手枪转轮回味记忆。",
      "anchors": [{"anchor_id": "E0006"}, {"anchor_id": "E0007"}, {"anchor_id": "E0008"}, {"anchor_id": "E0010"}]
    },
    {
      "event_id": "EV-C0003-03",
      "event": "周明瑞发现克莱恩的记忆失去连贯性且缺失手枪来源等具体内容。",
      "anchors": [{"anchor_id": "E0012"}, {"anchor_id": "E0013"}, {"anchor_id": "E0014"}]
    },
    {
      "event_id": "EV-C0003-04",
      "event": "周明瑞发现克莱恩掌握的知识也残缺，认为其回大学恐无法毕业。",
      "anchors": [{"anchor_id": "E0018"}, {"anchor_id": "E0019"}, {"anchor_id": "E0020"}]
    },
    {
      "event_id": "EV-C0003-05",
      "event": "周明瑞从记忆中得知两天后要参加廷根大学历史系的面试。",
      "anchors": [{"anchor_id": "E0022"}, {"anchor_id": "E0023"}]
    },
    {
      "event_id": "EV-C0003-06",
      "event": "周明瑞得知导师给了一份廷根大学和一份贝克兰德大学的推荐信。",
      "anchors": [{"anchor_id": "E0024"}, {"anchor_id": "E0025"}]
    },
    {
      "event_id": "EV-C0003-07",
      "event": "窗外红月西斜至东方微亮时，里面房间传出梅丽莎醒来的动静。",
      "anchors": [{"anchor_id": "E0027"}, {"anchor_id": "E0028"}, {"anchor_id": "E0029"}, {"anchor_id": "E0030"}]
    },
    {
      "event_id": "EV-C0003-08",
      "event": "周明瑞受克莱恩记忆影响对梅丽莎产生亲妹妹般的感觉。",
      "anchors": [{"anchor_id": "E0031"}, {"anchor_id": "E0032"}]
    },
    {
      "event_id": "EV-C0003-09",
      "event": "周明瑞从记忆中得知梅丽莎从小喜欢机械并立志做蒸汽机械师。",
      "anchors": [{"anchor_id": "E0048"}, {"anchor_id": "E0049"}]
    },
    {
      "event_id": "EV-C0003-10",
      "event": "周明瑞得知班森支持梅丽莎就读廷根技术学校蒸汽与机械系。",
      "anchors": [{"anchor_id": "E0051"}, {"anchor_id": "E0052"}, {"anchor_id": "E0055"}]
    },
    {
      "event_id": "EV-C0003-11",
      "event": "周明瑞得知班森供职的公司大幅缩水并裁员，班森为保住工作接受了繁重任务。",
      "anchors": [{"anchor_id": "E0058"}, {"anchor_id": "E0059"}, {"anchor_id": "E0060"}, {"anchor_id": "E0061"}]
    },
    {
      "event_id": "EV-C0003-12",
      "event": "周明瑞得知克莱恩在大学因基础不足而勉强以中等成绩毕业。",
      "anchors": [{"anchor_id": "E0065"}, {"anchor_id": "E0070"}, {"anchor_id": "E0071"}, {"anchor_id": "E0072"}]
    },
    {
      "event_id": "EV-C0003-13",
      "event": "里面房间门打开，周明瑞醒转并慌忙将左轮手枪丢进书桌抽屉。",
      "anchors": [{"anchor_id": "E0074"}, {"anchor_id": "E0075"}, {"anchor_id": "E0078"}, {"anchor_id": "E0079"}]
    },
    {
      "event_id": "EV-C0003-14",
      "event": "梅丽莎听到动静疑惑望来，周明瑞强做镇定关上抽屉掩盖手枪。",
      "anchors": [{"anchor_id": "E0080"}, {"anchor_id": "E0081"}, {"anchor_id": "E0085"}, {"anchor_id": "E0086"}]
    },
    {
      "event_id": "EV-C0003-15",
      "event": "周明瑞触摸太阳穴确定头上的伤口已经愈合。",
      "anchors": [{"anchor_id": "E0087"}, {"anchor_id": "E0088"}]
    },
    {
      "event_id": "EV-C0003-16",
      "event": "周明瑞从抽屉拿出父亲遗留的怀表并按开表盖。",
      "anchors": [{"anchor_id": "E0089"}, {"anchor_id": "E0090"}, {"anchor_id": "E0091"}]
    },
    {
      "event_id": "EV-C0003-17",
      "event": "周明瑞发现怀表秒针停顿不动且扭动顶端没有发条绷紧声。",
      "anchors": [{"anchor_id": "E0099"}, {"anchor_id": "E0100"}, {"anchor_id": "E0101"}, {"anchor_id": "E0102"}]
    },
    {
      "event_id": "EV-C0003-18",
      "event": "周明瑞没话找话说怀表好像又坏了。",
      "anchors": [{"anchor_id": "E0103"}]
    },
    {
      "event_id": "EV-C0003-19",
      "event": "梅丽莎拿走怀表，拔起顶端按钮转动使秒针走动并对好时间。",
      "anchors": [{"anchor_id": "E0105"}, {"anchor_id": "E0106"}, {"anchor_id": "E0107"}, {"anchor_id": "E0112"}, {"anchor_id": "E0113"}]
    },
    {
      "event_id": "EV-C0003-20",
      "event": "梅丽莎将怀表还给周明瑞。",
      "anchors": [{"anchor_id": "E0114"}]
    },
    {
      "event_id": "EV-C0003-21",
      "event": "周明瑞尴尬微笑，梅丽莎拿上洗漱用品前往公用盥洗室。",
      "anchors": [{"anchor_id": "E0115"}, {"anchor_id": "E0117"}]
    },
    {
      "event_id": "EV-C0003-22",
      "event": "周明瑞思考克莱恩自杀动静不小而一墙之隔的梅丽莎竟毫无察觉。",
      "anchors": [{"anchor_id": "E0123"}, {"anchor_id": "E0124"}, {"anchor_id": "E0125"}]
    },
    {
      "event_id": "EV-C0003-23",
      "event": "梅丽莎洗漱归来，让周明瑞拿出剩余面包并去买新面包、肉和豌豆。",
      "anchors": [{"anchor_id": "E0128"}, {"anchor_id": "E0131"}, {"anchor_id": "E0132"}]
    },
    {
      "event_id": "EV-C0003-24",
      "event": "梅丽莎生火煮茶，两人就着茶水分享了两条黑麦面包。",
      "anchors": [{"anchor_id": "E0134"}, {"anchor_id": "E0135"}, {"anchor_id": "E0138"}, {"anchor_id": "E0139"}]
    },
    {
      "event_id": "EV-C0003-25",
      "event": "梅丽莎吃完后再次叮嘱周明瑞买八磅面包以及羔羊肉和豌豆。",
      "anchors": [{"anchor_id": "E0143"}, {"anchor_id": "E0144"}, {"anchor_id": "E0145"}, {"anchor_id": "E0146"}]
    },
    {
      "event_id": "EV-C0003-26",
      "event": "周明瑞微笑点头答应。",
      "anchors": [{"anchor_id": "E0147"}, {"anchor_id": "E0148"}]
    },
    {
      "event_id": "EV-C0003-27",
      "event": "梅丽莎收拾好准备出门上课，开门时再次叮嘱周明瑞不要买多且班森周日才回。",
      "anchors": [{"anchor_id": "E0152"}, {"anchor_id": "E0154"}, {"anchor_id": "E0160"}, {"anchor_id": "E0161"}, {"anchor_id": "E0162"}]
    },
    {
      "event_id": "EV-C0003-28",
      "event": "周明瑞无奈回答答应。",
      "anchors": [{"anchor_id": "E0163"}]
    },
    {
      "event_id": "EV-C0003-29",
      "event": "周明瑞心里默念周日，思考北大陆历法与七位正统神灵的关联。",
      "anchors": [{"anchor_id": "E0164"}, {"anchor_id": "E0165"}, {"anchor_id": "E0169"}, {"anchor_id": "E0170"}]
    },
    {
      "event_id": "EV-C0003-30",
      "event": "周明瑞目送梅丽莎离开后叹气，将心思转移到转运仪式上。",
      "anchors": [{"anchor_id": "E0172"}, {"anchor_id": "E0173"}]
    }
  ]
}
